/* Headline figures for the directory stat band. `institutions` is what
 * this directory lists; `recognised` is the Ministry of Education and
 * Culture's own administrative branch (13 universities + 22 universities
 * of applied sciences), which is the officially published structure of
 * Finnish higher education. They differ by one: Hogskolan pa Aland is a
 * recognised Finnish higher education institution awarding Finnish
 * degrees, but it answers to the Government of Aland rather than to the
 * Ministry, so it is listed here and excluded from the official 35.
 *
 * `programmes` is the NATIONAL, deduplicated count of English-taught
 * bachelor's and master's degree programmes in Studyinfo -- not the sum
 * of the per-institution lists below, which counts a programme once per
 * institution that offers it. Quoting the larger number would overstate
 * how much choice exists. */
window.FI_PROGRAMME_TOTALS = {
  institutions: 36,
  recognised: 35,
  universities: 13,
  uas: 22,
  programmes: 691,
  doctoral: 104,
  listings: 1295
};
